//! Differential probe battery for the formatfloat port.
//!
//! Reads `scripts/fmt_vectors.txt` (generated by
//! `scripts/gen_fmt_vectors.py`; binary oracle = the reference
//! petitpy binary, harness oracle = the direct C harness built from
//! the original vendor sources with the reference build's compiler
//! and flags) and checks every case against the Rust port.
//! One case per line, TAB-separated:
//! `bits_hex <TAB> fmt <TAB> prec <TAB> sign <TAB> bufsize <TAB> expected`.
//! All failures are collected and reported at the end, so one bad
//! case does not hide the rest.

use crate::vendor::formatfloat::format_float_into_buf;

const VECTORS: &str = include_str!("../../scripts/fmt_vectors.txt");

#[test]
fn probe_vectors() {
    let mut failures: Vec<String> = Vec::new();
    let mut count = 0usize;

    for (lineno, line) in VECTORS.lines().enumerate() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        count += 1;
        let f: Vec<&str> = line.split('\t').collect();
        if f.len() != 6 {
            failures.push(format!("line {}: malformed: {:?}", lineno + 1, line));
            continue;
        }
        let bits = u64::from_str_radix(f[0], 16).unwrap();
        let value = f64::from_bits(bits);
        let fmt = f[1].as_bytes()[0];
        let prec: i32 = f[2].parse().unwrap();
        let sign = match f[3] {
            "0" => 0u8,
            "+" => b'+',
            "S" => b' ',
            other => {
                failures.push(format!("line {}: bad sign {:?}", lineno + 1, other));
                continue;
            }
        };
        let bufsize: usize = f[4].parse().unwrap();
        let want = f[5];

        let mut buf = vec![0u8; bufsize];
        let len = format_float_into_buf(value, fmt, prec, sign, &mut buf);
        let got_bytes = &buf[..len as usize];
        let got = String::from_utf8_lossy(got_bytes);
        if got != want {
            failures.push(format!(
                "line {}: bits={} fmt={} prec={} sign={} bufsize={}: got {:?} want {:?}",
                lineno + 1,
                f[0],
                fmt as char,
                prec,
                f[3],
                bufsize,
                got,
                want
            ));
        }
        if buf[len as usize] != 0 {
            failures.push(format!(
                "line {}: missing NUL terminator at {}",
                lineno + 1,
                len
            ));
        }
    }

    assert_eq!(count, 3440, "vector count changed; regenerate or update");
    assert!(
        failures.is_empty(),
        "{} of {} cases failed:\n{}",
        failures.len(),
        count,
        failures.iter().take(30).cloned().collect::<Vec<_>>().join("\n")
    );
}
